type AmtRec struct {
	ArAcct string
	ArAmt  decimal.Decimal
}

var WsEofFlag string = "N"
var WsBigTotal decimal.Decimal = decimal.NewFromInt(0)
var WsWrapTotal decimal.Decimal = decimal.NewFromInt(0)
var WsSafeTotal decimal.Decimal = decimal.NewFromInt(0)
var WsOverflows int64 = 0
var WsCount int64 = 0
var WsHalf decimal.Decimal = decimal.NewFromInt(0)
var WsAmtEd string
var WsWrapEd string
var WsSafeEd string
var WsHalfEd string

var amtFile *os.File
var amtReader *bufio.Reader
var curRec AmtRec

func formatEdited(val decimal.Decimal, picture string) string {
	// picture like ZZ,ZZ9.99 or ZZ,ZZ9.9
	// count integer digits (Z+9 before dot) and scale (digits after dot)
	dotIdx := strings.Index(picture, ".")
	intPic := picture
	scale := 0
	if dotIdx >= 0 {
		intPic = picture[:dotIdx]
		scale = len(picture) - dotIdx - 1
	}
	// integer picture length excluding commas
	intDigits := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intDigits++
		}
	}
	width := len(picture) // includes commas and dot

	// truncate toward zero to scale
	trunc := val.Truncate(int32(scale))

	// handle sign: all fields are unsigned in this program, assume >=0
	// integer part and fractional part
	// fractional: exactly scale digits, zero padded
	// integer: exactly intDigits digits, truncated high-order if needed, zero padded
	// then apply Z suppression and comma handling

	// Get integer and fraction strings
	// Use string representation of trunc with scale
	// trunc is decimal with at most scale fractional digits (maybe less due to truncate)
	// Build integer part as string of intDigits digits (low-order)
	intPart := trunc.Truncate(0)
	// intPart >=0
	intStr := intPart.StringFixed(0) // no decimals
	// intStr may be large; keep low-order digits
	if len(intStr) > intDigits {
		intStr = intStr[len(intStr)-intDigits:]
	}
	// pad with leading zeros to intDigits
	if len(intStr) < intDigits {
		intStr = strings.Repeat("0", intDigits-len(intStr)) + intStr
	}
	// fractional part
	fracStr := ""
	if scale > 0 {
		// fractional digits
		// trunc * 10^scale -> integer
		shifted := trunc.Shift(int32(scale)).Truncate(0)
		// fractional = shifted mod 10^scale, positive
		// For positive numbers, we can get via string
		// Use modulo arithmetic with decimal
		// Compute integer part shift
		// Easier: format with StringFixed(scale) and split
		s := trunc.StringFixed(int32(scale))
		parts := strings.SplitN(s, ".", 2)
		if len(parts) == 2 {
			fracStr = parts[1]
		} else {
			fracStr = strings.Repeat("0", scale)
		}
		// ensure length scale (pad)
		if len(fracStr) < scale {
			fracStr = fracStr + strings.Repeat("0", scale-len(fracStr))
		} else if len(fracStr) > scale {
			fracStr = fracStr[len(fracStr)-scale:]
		}
	}

	// Now build edited output according to picture pattern
	// Walk picture left to right, consuming intStr digits for Z/9 positions,
	// copying ',' and '.' literally initially.
	// Then apply Z suppression: leading zeros in Z positions become spaces,
	// commas in suppressed zone become spaces.
	out := make([]byte, width)
	intIdx := 0
	for i := 0; i < width; i++ {
		pc := picture[i]
		switch pc {
		case 'Z', '9':
			out[i] = intStr[intIdx]
			intIdx++
		case ',':
			out[i] = ','
		case '.':
			out[i] = '.'
		default:
			out[i] = pc
		}
	}
	// For integer part, apply Z suppression
	// Find the dot position if any
	// suppression zone is from start up to but not including the last leading zero handling?
	// COBOL: Z suppresses leading zeros; a comma inside suppressed zone becomes space.
	// The rightmost '9' forces a digit.
	// Implementation: scan integer picture positions left to right; if we are still in leading-zero suppression (all digits seen so far are '0' and current digit is '0' and the picture char is Z), then replace digit with space; if it's a comma and still in suppression, replace with space.
	// Suppression ends when we encounter a non-zero digit or a '9' position.
	// For ZZ,ZZ9 pattern, the '9' ensures at least one digit.
	suppressing := true
	// Need to know which positions correspond to digit slots
	// Walk over output positions that are digit slots in integer part (before dot)
	for i := 0; i < width; i++ {
		pc := picture[i]
		if pc == '.' {
			break
		}
		if pc == 'Z' {
			if suppressing {
				if out[i] == '0' {
					out[i] = ' '
				} else {
					suppressing = false
				}
			}
		} else if pc == '9' {
			// 9 always prints, ends suppression
			suppressing = false
		} else if pc == ',' {
			if suppressing {
				out[i] = ' '
			}
		}
	}
	// fractional part already placed? For fractional positions after dot, picture has only 9s
	// We have already placed int part, but fractional digits need to replace the 9 positions after dot
	// Our out currently has int digits plus placeholders for fractional 9s (currently zero chars from intStr? Actually we filled only intDigits; after dot we incorrectly filled with intStr remaining? Let's handle fractional separately.)
	// Simpler: rebuild correctly: integer part already in out[0:dotIdx], fractional after.
	if dotIdx >= 0 {
		fracIdx := 0
		for i := dotIdx + 1; i < width; i++ {
			// picture[i] should be '9'
			out[i] = fracStr[fracIdx]
			fracIdx++
		}
		out[dotIdx] = '.'
	}
	return string(out)
}

func moveToWrap() {
	// MOVE WS-BIG-TOTAL TO WS-WRAP-TOTAL : keep low-order 5 integer digits, same scale 2
	// Truncate WS-BIG-TOTAL to 2 decimals already, then wrap
	WsWrapTotal = wrapDecimal(WsBigTotal, 5, 2)
}

func wrapDecimal(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// keep low-order intDigits of integer part, scale fractional truncated
	t := v.Truncate(scale)
	// split
	sign := t.Sign()
	if sign < 0 {
		t = t.Neg()
	}
	intPart := t.Truncate(0)
	fracPart := t.Sub(intPart) // 0 <= frac <1
	// compute intPart mod 10^intDigits
	mod := decimal.NewFromInt(1)
	for i := 0; i < intDigits; i++ {
		mod = mod.Mul(decimal.NewFromInt(10))
	}
	// intPart % mod
	// Use intPart as decimal, do Div mod via string? Use Int part via decimal mod
	// decimal does not have mod directly, we can compute remainder = intPart - floor(intPart/mod)*mod
	q := intPart.Div(mod).Truncate(0)
	rem := intPart.Sub(q.Mul(mod))
	result := rem.Add(fracPart)
	if sign < 0 {
		result = result.Neg()
	}
	return result
}

func addToBigTotal(amt decimal.Decimal) {
	sum := WsBigTotal.Add(amt)
	// target scale 2 truncate
	sum = sum.Truncate(2)
	// wrap to 7 integer digits
	WsBigTotal = wrapDecimal(sum, 7, 2)
}

func tryAddSafeTotal(amt decimal.Decimal) (decimal.Decimal, bool) {
	sum := WsSafeTotal.Add(amt)
	sum = sum.Truncate(2)
	// check overflow: integer digits >5 => >=100000
	intPart := sum.Truncate(0).Abs()
	limit := decimal.NewFromInt(100000) // 10^5
	if intPart.GreaterThanOrEqual(limit) {
		return sum, true // overflow
	}
	return sum, false
}

func MAIN_PARA() {
	f, err := os.Open("input.dat")
	if err != nil {
		// if file not exists, treat as empty
		f = nil
		WsEofFlag = "Y"
	} else {
		amtFile = f
		amtReader = bufio.NewReader(f)
	}
	READ_PARA()
	for !INPUT_DONE() {
		PROCESS_PARA()
	}
	if amtFile != nil {
		amtFile.Close()
	}
	SUMMARY_PARA()
}

func INPUT_DONE() bool { return WsEofFlag == "Y" }

func READ_PARA() {
	if amtReader == nil {
		WsEofFlag = "Y"
		return
	}
	line, err := amtReader.ReadString('\n')
	if err != nil {
		// if we got data before EOF, process it; ReadString returns data + EOF
		if len(line) == 0 {
			WsEofFlag = "Y"
			return
		}
		// line without newline at EOF -> process it, next read will be EOF
	} else {
		// strip trailing \r\n
		line = strings.TrimRight(line, "\r\n")
	}
	// pad to 11
	if len(line) < 11 {
		line = line + strings.Repeat(" ", 11-len(line))
	}
	if len(line) > 11 {
		line = line[:11]
	}
	// detect empty? Still parse
	arAcct := line[0:4]
	arAmtRaw := line[4:11]
	// PIC 9(5)V99 => 7 digits implied 2 decimals
	// If contains spaces? Treat spaces as zeros? But input should be digits
	trimmed := strings.TrimSpace(arAmtRaw)
	if trimmed == "" {
		trimmed = "0"
	}
	// remove non-digit? Assume digits only
	// parse as integer
	// Keep all digits including leading zeros
	// If arAmtRaw contains spaces inside, remove spaces
	digits := ""
	for _, ch := range arAmtRaw {
		if ch >= '0' && ch <= '9' {
			digits += string(ch)
		}
	}
	if digits == "" {
		digits = "0"
	}
	n, _ := decimal.NewFromString(digits)
	// shift -2
	amt := n.Shift(-2)
	curRec = AmtRec{ArAcct: arAcct, ArAmt: amt}
	// If ReadString returned EOF with data, we will process this record and next call will set EOF
	// Need to peek if err != nil due to EOF, we still have record now; don't set EOF yet unless line was empty and err.
	// The above handling: if err == EOF and we have line, we shouldn't set EOF now; but our reader will on next call return 0.
	// So if err != nil and len(line after trim) ==0? We already returned? For non-empty line with EOF, keep EOF flag N for now; next call will get empty.
	// To avoid losing EOF flag, check if err != nil: we need to remember that next read should be EOF, but not now.
	// Simplest: if err != nil (EOF) we have consumed last line, but we still have this record to process; keep flag N now, but set a pending EOF?
	// We'll handle by checking if err != nil we set a flag to indicate next read is EOF by closing reader after this line? Alternative: just keep reader but next ReadString will return 0.
	// So don't set done now.
	if err != nil && len(line) == 0 {
		WsEofFlag = "Y"
	}
	// If err != nil and we had data, we leave WsEofFlag = "N" so PROCESS will run, then next READ_PARA will hit EOF.
}

func PROCESS_PARA() {
	// ADD AR-AMT TO WS-BIG-TOTAL
	addToBigTotal(curRec.ArAmt)
	// MOVE WS-BIG-TOTAL TO WS-WRAP-TOTAL
	moveToWrap()
	// ADD AR-AMT TO WS-SAFE-TOTAL ON SIZE ERROR PERFORM OVERFLOW-PARA
	sum, overflow := tryAddSafeTotal(curRec.ArAmt)
	if overflow {
		OVERFLOW_PARA()
		// BUG: following statements are inside ON SIZE ERROR branch
		WsCount++
		// COMPUTE WS-HALF = AR-AMT / 2 (truncated, no rounded)
		// scale of WS-HALF is 1 (PIC 9(5)V9)
		half := curRec.ArAmt.Div(decimal.NewFromInt(2))
		half = half.Truncate(1)
		half = wrapDecimal(half, 5, 1)
		WsHalf = half
		WsAmtEd = formatEdited(curRec.ArAmt, "ZZ,ZZ9.99")
		WsWrapEd = formatEdited(WsWrapTotal, "ZZ,ZZ9.99")
		WsSafeEd = formatEdited(WsSafeTotal, "ZZ,ZZ9.99")
		WsHalfEd = formatEdited(WsHalf, "ZZ,ZZ9.9")
		fmt.Printf("%s %s %s %s %s\n", curRec.ArAcct, WsAmtEd, WsWrapEd, WsSafeEd, WsHalfEd)
	} else {
		WsSafeTotal = sum
		// When no overflow, the buggy scope means the following statements are SKIPPED
		// So we do not increment count, compute half, or display.
	}
	READ_PARA()
}

func SUMMARY_PARA() {
	// DISPLAY "RECORDS: " WS-COUNT (PIC 99 => width 2 zero-padded? Unedited numeric displays as per spec)
	// Unedited numeric DISPLAY prints zero-padded to digit count.
	// PIC 99 with value 5 => "05"
	countStr := fmt.Sprintf("%02d", WsCount)
	overStr := fmt.Sprintf("%02d", WsOverflows)
	fmt.Printf("RECORDS: %s\n", countStr)
	fmt.Printf("OVERFLOWS: %s\n", overStr)
}

func OVERFLOW_PARA() {
